<?phpnamespace frontend\models;use common\models\EventMemberRegistrations;use common\models\Events;use yii\base\Model;/** * ContactForm is the model behind the contact form. */class EventUserRegistration extends Model{    public $event_id;    public $first_name;    public $last_name;    public $email;    public $phone;    public $consent_to_the_processing_of_my_personal_data;    /**     * {@inheritdoc}     */    public function rules()    {        return [            [['event_id', 'first_name', 'last_name', 'email', 'phone', 'consent_to_the_processing_of_my_personal_data'], 'required'],            [['event_id'], 'integer'],            [['first_name', 'last_name', 'email', 'phone'], 'string', 'max' => 255],            ['consent_to_the_processing_of_my_personal_data', 'compare', 'compareValue' => 1, 'operator' => '==',                'message' => 'You must accept the terms.'],            [['event_id'], 'exist', 'skipOnError' => true, 'targetClass' => Events::class, 'targetAttribute' => ['event_id' => 'id']],        ];    }    public function save()    {        $model = new EventMemberRegistrations();        $model->event_id = $this->event_id;        $model->first_name = $this->first_name;        $model->last_name = $this->last_name;        $model->email = $this->email;        $model->phone = $this->phone;        return $model->save();    }}